def CZeroFiniteColumnBound (F : ℕ → X →L[𝕜] Y) (C : ℝ) : Prop :=
  ∀ (s : Finset ℕ) (x : ℕ → X) (b : ℝ), 0 ≤ b →
    (∀ i ∈ s, ‖x i‖ ≤ b) → ‖∑ i ∈ s, F i (x i)‖ ≤ C*b

